+ (UIImage *) draw:(int)number scale:(double)scale branchFacilityType:(NSString *)branchFacilityType color:(NSString *)color
{
    double width = DESIGISIZE.width * scale;
    double height = DESIGISIZE.height * scale;
    
    UIColor *iconColor = [self UIColorFromHexString:color];
    
    CGSize size = CGSizeMake(width, height);
    
    // 1.开启图形上下文，并将ImageContext放置到栈顶
    UIGraphicsBeginImageContextWithOptions(size, NO, 0);
    
    // 2.绘制图形（电柜设施）
    [self drawBranchFacilityIconWithFrame: CGRectMake(0, 0, width, height) number:number branchFacilityType:branchFacilityType resizing: BranchFacilityIconResizingBehaviorStretch iconColor:iconColor];
    
    // 3.从上下文中获取图片
    UIImage *image = UIGraphicsGetImageFromCurrentImageContext();
    
    // 4.关闭图形上下文
    UIGraphicsEndImageContext();
    
    return image;
}

